<script lang="ts">
 import {onMount} from 'svelte';import {GUNS,CARS} from '$lib/hood-state';import type {createHood,HUD} from '$lib/hood-world';
 let host:HTMLDivElement;let game:ReturnType<typeof createHood>|undefined;let avatar=$state(1);let h=$state<HUD>({ready:false,error:'',cash:500,ammo:17,reserve:136,gun:'Glock',health:100,stamina:100,heat:0,speed:0,driving:false,prompt:'',message:'',shop:null,mission:'',avatar:1,ownedGuns:['glock'],ownedCars:['compact'],car:'compact',mapX:0,mapZ:11,active:false});
 onMount(()=>{let disposed=false;import('$lib/hood-world').then(m=>{if(disposed)return;game=m.createHood(host,s=>{if(s.avatar!==h.avatar)avatar=s.avatar;h=s})}).catch(()=>h={...h,error:'This browser could not start the 3D world. Try a browser with WebGL enabled.'});return()=>{disposed=true;game?.dispose()}});
 const titles={corner:'Corner Mart',weapons:'Block Arms',dealer:'Doodz Motors',repair:'Repair & Tune',police:'Doodz Police'};
</script>
<svelte:head><title>CryptoDoodz — The Block</title><meta name="description" content="Explore the CryptoDoodz neighborhood. Drive, visit shops, take delivery jobs and practice at the range."/></svelte:head>
<main class="hood"><div class="world" bind:this={host}></div><header><a href="/cryptodoodz/">CRYPTODOODZ <b>THE BLOCK</b></a><span class="mode">SOLO SANDBOX · LOCAL SAVE</span><button onclick={()=>game?.pause()}>Esc / Menu</button></header>
 <aside class="status"><strong>${h.cash.toLocaleString()} <small>GAME CASH</small></strong><p>{h.gun} <b>{h.ammo}</b><span> / {h.reserve}</span></p><div class="meter"><span style:width={`${h.stamina}%`}></span></div><small>STAMINA</small>{#if h.driving}<p>{Math.round(h.speed)} km/h · Car {Math.round(h.health)}%</p>{/if}{#if h.heat>.1}<p class="heat">POLICE HEAT {'★'.repeat(Math.ceil(h.heat))}</p>{/if}</aside>
 <aside class="map" aria-label="Neighborhood minimap"><div class="road north"></div><div class="road east"></div><span class="map-label" style="left:27%;top:30%">PD</span><span class="map-label" style="left:63%;top:30%">MART</span><span class="map-label" style="left:24%;top:65%">ARMS</span><span class="map-label" style="left:63%;top:65%">FIX</span><span class="map-label" style="left:81%;top:46%">CARS</span><span class="dot" style:left={`${50+h.mapX/1.4}%`} style:top={`${50+h.mapZ/1.4}%`}></span><small>N ↑</small></aside>
 {#if h.active&&!h.shop}<div class="crosshair">+</div>{/if}
 <div class="bottom"><p class="mission">{h.mission}</p>{#if h.message}<p class="message" role="status">{h.message}</p>{/if}{#if h.prompt}<p class="prompt">{h.prompt}</p>{/if}<p class="controls">WASD move <span>·</span> Shift sprint <span>·</span> Mouse aim <span>·</span> Click shoot <span>·</span> R reload <span>·</span> E shop <span>·</span> F drive <span>·</span> Space jump</p></div>
 {#if !h.active&&!h.shop}<div class="overlay"><section class="panel"><p class="eyebrow">WELCOME TO THE NEIGHBORHOOD</p><h1>The Block</h1><p>Grab a ride, pick up a delivery, or hit the target range. Your Glock and compact car are ready.</p><div class="start-controls"><label>Dood # <input type="number" min="1" max="1000" bind:value={avatar}/></label><button disabled={!h.ready} onclick={()=>game?.setAvatar(avatar)}>Change Dood</button></div>{#if h.error}<p role="alert">{h.error}</p><button onclick={()=>game?.setAvatar(avatar)}>Retry</button>{/if}<button class="primary" disabled={!h.ready} onclick={()=>game?.resume()}>{h.ready?'Enter the block':'Loading your Dood…'}</button><p class="fine">Desktop controls. Click the world to capture your mouse; Esc releases it. Right-drag also turns the camera. Progress saves on this device. Purchases use game cash, not crypto.</p></section></div>{/if}
 {#if h.shop}<div class="overlay"><section class="panel shop"><div class="shop-title"><h2>{titles[h.shop]}</h2><button onclick={()=>game?.closeShop()} aria-label="Close shop">✕</button></div><p class="cash">${h.cash.toLocaleString()} available</p>
 {#if h.shop==='weapons'}{#each GUNS as gun}<article><div><strong>{gun.name}</strong><small>{gun.capacity} rounds · {gun.automatic?'Automatic':'Semi-auto'} · Range damage {gun.damage}</small></div><button onclick={()=>game?.buy('gun',gun.id)} disabled={!h.ownedGuns.includes(gun.id)&&h.cash<gun.price}>{h.ownedGuns.includes(gun.id)?'Equip':`$${gun.price}`}</button></article>{/each}<button onclick={()=>game?.service('ammo')}>Ammo refill · $40</button>
 {:else if h.shop==='dealer'}{#each CARS as car}<article><div><strong>{car.name}</strong><small>Up to {Math.round(car.speed*3.6)} km/h</small></div><button onclick={()=>game?.buy('car',car.id)} disabled={!h.ownedCars.includes(car.id)&&h.cash<car.price}>{h.ownedCars.includes(car.id)?'Bring to spawn':`$${car.price}`}</button></article>{/each}<p class="fine">Your car appears by the central intersection. Walk up and press F.</p>
 {:else if h.shop==='repair'}<p>Vehicle condition: {Math.round(h.health)}%</p><button class="primary" disabled={h.cash<90} onclick={()=>game?.service('repair')}>Repair vehicle · $90</button>
 {:else if h.shop==='corner'}<article><div><strong>Snack & soda</strong><small>Restore your stamina</small></div><button disabled={h.cash<15} onclick={()=>game?.service('snack')}>$15</button></article><article><div><strong>Ammo box</strong><small>85 rounds</small></div><button disabled={h.cash<40} onclick={()=>game?.service('ammo')}>$40</button></article>
 {:else}<p>Help the neighborhood with a delivery. Take it to the marked business and press E to collect $180.</p><button class="primary" onclick={()=>game?.service('job')}>Take a delivery job</button><p class="fine">Practice at the range. Firing elsewhere attracts police and can result in a $75 citation.</p>{/if}
 {#if h.message}<p role="status">{h.message}</p>{/if}<button class="back" onclick={()=>game?.closeShop()}>Back to the block →</button></section></div>{/if}
</main>
